export function DirectMessageInterface({ townsDmId, ... }) {
  // ✅ SDK Pattern - no join() needed
  const { data: dm } = useDm(townsDmId);
  const { data: events, isLoading } = useTimeline(townsDmId);
  const { sendMessage, isPending: isSending } = useSendMessage(townsDmId);
  const { userId: myUserId } = useMyMember(townsDmId);
  const { redact } = useRedact(townsDmId);

  // Filter for ChannelMessage events
  const messages = (events || []).filter(
    (event) => event.content?.kind === RiverTimelineEvent.ChannelMessage
  );

  // Use createdAtEpochMs for timestamps
  const timestamp = event.createdAtEpochMs || Date.now();

  // Send messages directly
  const handleSendMessage = async () => {
    if (!messageInput.trim() || isSending) return;
    try {
      await sendMessage(messageInput);
      setMessageInput('');
    } catch (error: any) {
      // Handle Towns network errors
      const errorMsg = error.message?.toLowerCase() || '';
      if (errorMsg.includes('unimplemented') || errorMsg.includes('404')) {
        toast.error('⚠️ Towns network issue. Please try again in a moment.');
      } else if (errorMsg.includes('miniblock')) {
        toast.error('⏱️ Channel syncing. Wait a moment and try again.');
      } else {
        toast.error('Failed to send message. Please try again.');
      }
    }
  };
}
```

